sys_script_include.script:
var CiscoSecureAccessPreCheck = Class.create();
CiscoSecureAccessPreCheck.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    runCheck: function () {
        var errors = [];

        // --- Update Set Check ---
        var updateSet = gs.getSession().getCurrentUpdateSet();
        if (!updateSet || updateSet === 'Global') {
            errors.push('⚠️ No update set selected or update set is set to "Global".');
        }

        // --- Table and Field Definitions ---
        var tables = [
            { name: 'em_event_test', label: 'Event', fields: [
                { label: 'Rule Name', name: 'u_rule_name' },
                { label: 'API Key', name: 'u_api_key' }
            ] },
            { name: 'em_alert', label: 'Alert', fields: [
                { label: 'Rule Name', name: 'u_rule_name' },
                { label: 'API Key', name: 'u_api_key' }
            ] },
            { name: 'cisco_secure_access_token', label: 'Cisco Secure Access Token', fields: [
                { label: 'Access Token', name: 'u_access_token' },
                { label: 'API Key', name: 'u_api_key' },
                { label: 'Created On', name: 'u_created_on' },
                { label: 'Expires In', name: 'u_expires_in' },
                { label: 'Expiry Date/Time', name: 'u_expiry_date_time' },
                { label: 'Status', name: 'u_status' },
                { label: 'Token Type', name: 'u_token_type' }
            ] },
            { name: 'u_cisco_secure_access_private_resources', label: 'Cisco Secure Access Private Resources', fields: [] },
            { name: 'u_cisco_secure_access_private_resources_group', label: 'Cisco Secure Access Private Resources Group', fields: [] },
            { name: 'u_cisco_secure_access_discovered_application', label: 'Cisco Secure Access Discovered Application', fields: [] },
            { name: 'u_cisco_secure_access_application_list', label: 'Cisco Secure Access Application List', fields: [] },
            { name: 'u_cisco_secure_access_destinations', label: 'Cisco Secure Access Destinations', fields: [] },
            { name: 'u_cisco_secure_access_destination_list', label: 'Cisco Secure Access Destination List', fields: [] },
            { name: 'u_cmdb_ci_application', label: 'CMDB CI Application', fields: [] }
        ];

        // --- Table and Field Existence Check ---
        for (var i = 0; i < tables.length; i++) {
            var table = tables[i];

            // Table existence
            var tableGR = new GlideRecord('sys_db_object');
            tableGR.addQuery('name', table.name);
            tableGR.query();
            if (tableGR.next()) {
                errors.push('❌ Table already exists: ' + table.name + ' (Label: ' + table.label + ')');
            }

            // Field existence
            for (var j = 0; j < table.fields.length; j++) {
                var field = table.fields[j];
                var fieldGR = new GlideRecord('sys_dictionary');
                fieldGR.addQuery('name', table.name);
                fieldGR.addQuery('element', field.name);
                fieldGR.query();
                if (fieldGR.next()) {
                    errors.push('❌ Field "' + field.name + '" already exists on table "' + table.name + '"');
                }
            }

            // Warn if system-like prefix
            if (table.name.startsWith('em_')) {
                errors.push('⚠️ Warning: Table "' + table.name + '" may conflict with system/Event Management tables.');
            }
        }

        gs.info("CiscoSecureAccessPreCheck runCheck executed. Errors found: " + errors.length);
        return JSON.stringify(errors);
    },

    type: 'CiscoSecureAccessPreCheck'
});
